source='''from collections import Counter
from math import isqrt

def transform(grid):
    h, w = len(grid), len(grid[0])
    n = (isqrt(4 * h + 5) - 1) // 2
    if h != w or n * (n + 1) - 1 != h:
        raise ValueError("expected a square self-similar tile grid")
    pitch = n + 1

    # Each small N-by-N tile contains the same pattern as the N-by-N
    # arrangement of tiles. The color-3 band marks the missing macro row/column.
    patterns = []
    for tr in range(n):
        for tc in range(n):
            r0, c0 = tr * pitch, tc * pitch
            tile = tuple(tuple(int(grid[r0 + dr][c0 + dc] == 2)
                               for dc in range(n)) for dr in range(n))
            if any(any(row) for row in tile):
                patterns.append(tile)
    if not patterns:
        raise ValueError("no pattern tiles found")
    pattern = Counter(patterns).most_common(1)[0][0]

    out = [[0] * w for _ in range(h)]
    for tr in range(n):
        for tc in range(n):
            if not pattern[tr][tc]:
                continue
            r0, c0 = tr * pitch, tc * pitch
            for dr in range(n):
                for dc in range(n):
                    if pattern[dr][dc]:
                        out[r0 + dr][c0 + dc] = 2
            # Mark the pixel indexed by this tile's macro-grid coordinate.
            if pattern[tr][tc]:
                out[r0 + tr][c0 + tc] = 8
    return out
'''
